def run_length(s: str) -> str:
    """Run-length encode: each maximal run of a character c of length k becomes c followed by k. 'aaab' -> 'a3b1'."""
    if not s:
        return ''

    result = []
    count = 1
    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = s[i]
            count = 1

    result.append(f"{current_char}{count}")
    return ''.join(result)

