def gcd(a: int, b: int) -> int:
    """Greatest common divisor of two non-negative integers, not both zero."""
    # Handle the case where one number is 0
    if a == 0:
        return b
    if b == 0:
        return a

    # Euclidean algorithm
    while b != 0:
        a, b = b, a % b
    return a
