def merge_intervals(xs: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """Merge overlapping closed intervals; return them sorted by start. Touching intervals (1,2),(2,3) merge."""
    if not xs:
        return []

    sorted_xs = sorted(xs)
    merged = [sorted_xs[0]]

    for start, end in sorted_xs[1:]:
        last_start, last_end = merged[-1]

        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged

